/**
 * D28 drift guard for the schema-free capability facts addons read (the state-leaves table is proved in
 * addon-osd-manager, next to the walker that generates it) from
 * `@camstack/types/addon` instead of `ALL_CAPABILITY_DEFINITIONS`.
 *
 * The tables are generated by running the real derivation over every cap
 * definition; this spec re-derives the truth from the live definitions (it may
 * import the barrel — it is a spec) and fails the moment codegen is skipped
 * after a `.cap.ts` change.
 */
import { describe, expect, it } from 'vitest'
import { ALL_CAPABILITY_DEFINITIONS } from '../generated/capability-router-map.js'
import { CAP_ADVANCE_FIELDS } from '../addon.js'

describe('CAP_ADVANCE_FIELDS (generated)', () => {
  it('equals the field each cap declares in events[*].fromState { on: advance }', () => {
    const truth = Object.fromEntries(
      ALL_CAPABILITY_DEFINITIONS.flatMap((def): [string, string][] => {
        const fromState = Object.values(def.events ?? {}).find(
          (event) => event.fromState?.on === 'advance',
        )?.fromState
        return fromState === undefined ? [] : [[def.name, fromState.field]]
      }),
    )
    expect(CAP_ADVANCE_FIELDS).toEqual(truth)
    expect(CAP_ADVANCE_FIELDS['doorbell']).toBe('lastPressedAt')
  })
})
